while True:
    ret, frame = cap.read()   # grab the next frame
    if not ret:
        break                 # camera disconnected or video ended
    # ... process frame ...
    cv2.imshow("Window", frame)
    if cv2.waitKey(1) & 0xFF == ord('q'):
        break                 # let the user quit cleanly
cap.release()
cv2.destroyAllWindows()

try:
    cap = cv2.VideoCapture(config.CAMERA_INDEX)
    if not cap.isOpened():
        raise RuntimeError(f"Could not open camera index {config.CAMERA_INDEX}")
    # ... main loop ...
except KeyboardInterrupt:
    logger.info("Shutdown requested by user (Ctrl+C).")
except Exception as e:
    logger.error(f"Unexpected error: {e}")
finally:
    cap.release()
    cv2.destroyAllWindows()
    logger.info("Resources cleaned up. Application exited.")

